def gen(rng):
    T = 'Juspay'
    letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
    tests = ['Juspay', 'juspay', 'J', 'Jusp', 'Juspa', 'JUSPAY', 'Juspayy', 'yapsuJ', 'JJuuspppaaay', 'ayJuspay', 'JuspayJuspay']

    def with_target(noise_len):
        pos = sorted(rng.sample(range(noise_len + 6), 6))
        out = []
        k = 0
        for i in range(noise_len + 6):
            if k < 6 and i == pos[k]:
                out.append(T[k])
                k += 1
            else:
                out.append(rng.choice(letters))
        return ''.join(out)

    for _ in range(12):
        tests.append(with_target(rng.randint(0, 40)))
    for _ in range(10):
        tests.append(''.join(rng.choice('Juspay') for _ in range(rng.randint(1, 30))))
    for _ in range(6):
        tests.append(''.join(rng.choice('JuspayjUSPAY') for _ in range(rng.randint(5, 40))))
    # large
    n = 10**6
    tests.append('Jusp' + 'x' * (n - 6) + 'ay')
    tests.append(with_target(n - 6))
    tests.append(''.join(rng.choice('Juspa') for _ in range(n)))
    tests.append('J' * 300000 + 'u' * 200000 + 's' * 200000 + 'p' * 100000 + 'a' * 100000 + 'y' * 100000)
    return tests

